<?php
declare(strict_types=1);

final class PlanningWorkProgressService
{
    public function __construct(private PDO $pdo) {}

    public function chantiers(): array
    {
        return $this->pdo->query("SELECT c.id,c.code,c.titre
            FROM chantier_banamur c
            WHERE c.archived_at IS NULL
              AND c.closed_date IS NULL
              AND COALESCE(c.planning_is_office_hub,0)=0
            ORDER BY c.code,c.titre")->fetchAll(PDO::FETCH_ASSOC) ?: [];
    }

    public function preparations(int $chantierId): array
    {
        $q=$this->pdo->prepare("SELECT DISTINCT p.id,p.titre,m.id AS meeting_id,m.meeting_date,m.status,m.report_code,m.closed_at
            FROM planning_chantier_meeting_preparations p
            JOIN planning_chantier_meetings m
              ON m.preparation_id=p.id
             AND m.status='closed'
             AND m.archived_at IS NULL
            WHERE p.archived_at IS NULL
              AND (
                  EXISTS(SELECT 1 FROM planning_chantier_meeting_action_points ap
                      WHERE ap.preparation_id=p.id
                        AND ap.chantier_id=:chantier
                        AND ap.archived_at IS NULL
                        AND COALESCE(ap.status,'open')<>'cancelled')
                  OR EXISTS(SELECT 1 FROM planning_chantier_meeting_custom_sections cs
                      WHERE cs.preparation_id=p.id AND cs.chantier_id=:custom_chantier AND cs.archived_at IS NULL)
                  OR JSON_CONTAINS(IF(JSON_VALID(p.chantier_ids_json),p.chantier_ids_json,'[]'),:chantier_json,'$')
              )
            ORDER BY m.meeting_date DESC,m.closed_at DESC,m.id DESC");
        $q->execute(['chantier'=>$chantierId,'custom_chantier'=>$chantierId,'chantier_json'=>(string)$chantierId]);return $q->fetchAll(PDO::FETCH_ASSOC) ?: [];
    }

    public function report(int $chantierId,int $preparationId): array
    {
        $q=$this->pdo->prepare("SELECT ap.id,ap.section_title,ap.task_title,ap.progress,ap.status,ap.old_deadline,ap.new_deadline,COALESCE(w.unit_label,'ens') unit_label,COALESCE(w.planned_quantity,1) planned_quantity,COALESCE(w.client_billed_amount,0) client_billed_amount,COALESCE(w.observation,'') observation FROM planning_chantier_meeting_action_points ap LEFT JOIN planning_chantier_work_progress w ON w.action_point_id=ap.id WHERE ap.chantier_id=:chantier AND ap.preparation_id=:preparation AND ap.archived_at IS NULL AND COALESCE(ap.status,'open')<>'cancelled' ORDER BY ap.ligne_devis_id,ap.debourse_id,ap.sort_order,ap.id");
        $q->execute(['chantier'=>$chantierId,'preparation'=>$preparationId]);$rows=$q->fetchAll(PDO::FETCH_ASSOC) ?: [];
        $sub=$this->pdo->prepare("SELECT cl.id,cl.action_point_id,cl.label,cl.completed_at,COALESCE(w.unit_label,'ens') unit_label,COALESCE(w.planned_quantity,1) planned_quantity,COALESCE(w.client_billed_amount,0) client_billed_amount,COALESCE(w.observation,'') observation FROM planning_chantier_meeting_action_point_checklist cl JOIN planning_chantier_meeting_action_points ap ON ap.id=cl.action_point_id LEFT JOIN planning_chantier_work_progress_checklist w ON w.checklist_id=cl.id WHERE ap.chantier_id=:chantier AND ap.preparation_id=:preparation AND ap.archived_at IS NULL AND cl.archived_at IS NULL ORDER BY cl.sort_order,cl.id");$sub->execute(['chantier'=>$chantierId,'preparation'=>$preparationId]);$subtasks=[];foreach($sub->fetchAll(PDO::FETCH_ASSOC)?:[]as$item){$done=!empty($item['completed_at']);$item['progress']=$done?100:0;$item['executed_quantity']=(float)$item['planned_quantity']*($done?1:0);$item['executed_billed_amount']=(float)$item['client_billed_amount']*($done?1:0);$subtasks[(int)$item['action_point_id']][]=$item;}
        $customMetaQuery=$this->pdo->prepare('SELECT item_key,unit_label,planned_quantity,client_billed_amount,observation FROM planning_chantier_work_progress_custom WHERE preparation_id=:preparation AND chantier_id=:chantier');$customMetaQuery->execute(['preparation'=>$preparationId,'chantier'=>$chantierId]);$customMeta=[];foreach($customMetaQuery->fetchAll(PDO::FETCH_ASSOC)?:[]as$meta)$customMeta[(string)$meta['item_key']]=$meta;
        $customQuery=$this->pdo->prepare("SELECT id,title,start_date,end_date,payload_json FROM planning_chantier_meeting_custom_sections WHERE preparation_id=:preparation AND chantier_id=:chantier AND archived_at IS NULL ORDER BY sort_order,id");$customQuery->execute(['preparation'=>$preparationId,'chantier'=>$chantierId]);foreach($customQuery->fetchAll(PDO::FETCH_ASSOC)?:[]as$section){$tasks=json_decode((string)($section['payload_json']??'[]'),true);if(!is_array($tasks)||!$tasks)$tasks=[['title'=>$section['title'],'progress'=>0,'checklist'=>[]]];foreach(array_values($tasks)as$taskIndex=>$task){if(!is_array($task))continue;$key=(int)$section['id'].':t:'.$taskIndex;$meta=$customMeta[$key]??[];$customSub=[];foreach(array_values(is_array($task['checklist']??null)?$task['checklist']:[])as$subIndex=>$check){if(!is_array($check))continue;$subKey=$key.':s:'.$subIndex;$subMeta=$customMeta[$subKey]??[];$done=!empty($check['completed'])||!empty($check['completed_at']);$planned=(float)($subMeta['planned_quantity']??1);$amount=(float)($subMeta['client_billed_amount']??0);$customSub[]=['id'=>0,'source_type'=>'custom','storage_key'=>$subKey,'label'=>(string)($check['label']??('Sous-tâche '.($subIndex+1))),'completed_at'=>$done?'meeting':'','progress'=>$done?100:0,'unit_label'=>(string)($subMeta['unit_label']??'ens'),'planned_quantity'=>$planned,'executed_quantity'=>$planned*($done?1:0),'client_billed_amount'=>$amount,'executed_billed_amount'=>$amount*($done?1:0),'observation'=>(string)($subMeta['observation']??'')];}$rows[]=['id'=>0,'source_type'=>'custom','storage_key'=>$key,'section_title'=>(string)$section['title'],'task_title'=>(string)($task['title']??$section['title']),'progress'=>(float)($task['progress']??0),'status'=>'custom','old_deadline'=>(string)($task['old_deadline']??$section['start_date']??''),'new_deadline'=>(string)($task['new_deadline']??$section['end_date']??''),'unit_label'=>(string)($meta['unit_label']??'ens'),'planned_quantity'=>(float)($meta['planned_quantity']??1),'client_billed_amount'=>(float)($meta['client_billed_amount']??0),'observation'=>(string)($meta['observation']??''),'custom_subtasks'=>$customSub];}}
        foreach($rows as&$customRow){if(($customRow['source_type']??'')!=='custom')continue;if(preg_match('/^(\d+):t:(\d+)$/',(string)$customRow['storage_key'],$match))$customRow['id']=-(((int)$match[1]*1000)+(int)$match[2]+1);foreach($customRow['custom_subtasks']??[]as&$customSubtask)if(preg_match('/^(\d+):t:(\d+):s:(\d+)$/',(string)$customSubtask['storage_key'],$match))$customSubtask['id']=-(((int)$match[1]*10000)+((int)$match[2]*100)+(int)$match[3]+1);unset($customSubtask);}unset($customRow);
        $g=$this->pdo->prepare('SELECT section_title,client_billed_amount,observation FROM planning_chantier_work_progress_groups WHERE chantier_id=:chantier AND preparation_id=:preparation');$g->execute(['chantier'=>$chantierId,'preparation'=>$preparationId]);$groupData=[];foreach($g->fetchAll(PDO::FETCH_ASSOC)?:[] as$row)$groupData[(string)$row['section_title']]=$row;
        $groups=[];foreach($rows as$row){$name=trim((string)($row['section_title']??''))?:'Point de réunion';$groups[$name]??=['title'=>$name,'rows'=>[],'client_billed_amount'=>(float)($groupData[$name]['client_billed_amount']??0),'observation'=>(string)($groupData[$name]['observation']??'')];$planned=max(0,(float)$row['planned_quantity']);$rate=min(100,max(0,(float)$row['progress']));$row['subtasks']=($row['source_type']??'')==='custom'?($row['custom_subtasks']??[]):($subtasks[(int)$row['id']]??[]);$subBudget=array_sum(array_column($row['subtasks'],'client_billed_amount'));$billed=max(0,(float)$row['client_billed_amount']);if($billed<=0&&$subBudget>0)$billed=$subBudget;$row['client_billed_amount']=$billed;$row['executed_quantity']=$planned*$rate/100;$row['technical_rate']=$rate;$row['executed_billed_amount']=$row['subtasks']?array_sum(array_column($row['subtasks'],'executed_billed_amount')):$billed*$rate/100;$row['financial_rate']=$billed>0?min(100,$row['executed_billed_amount']/$billed*100):0;$groups[$name]['rows'][]=$row;}
        $overallBudget=0.0;$overallExecuted=0.0;$weightedTechnical=0.0;foreach($groups as&$group){$taskBudget=array_sum(array_map(fn($r)=>(float)$r['client_billed_amount'],$group['rows']));$groupBudget=(float)$group['client_billed_amount'];if($groupBudget<=0)$groupBudget=$taskBudget;$group['effective_budget']=$groupBudget;$groupExecuted=array_sum(array_map(fn($r)=>(float)$r['executed_billed_amount'],$group['rows']));$group['executed_amount']=$groupExecuted;$group['financial_rate']=$groupBudget>0?min(100,$groupExecuted/$groupBudget*100):0;$technical=$taskBudget>0?array_sum(array_map(fn($r)=>(float)$r['technical_rate']*(float)$r['client_billed_amount'],$group['rows']))/$taskBudget:(count($group['rows'])?array_sum(array_column($group['rows'],'technical_rate'))/count($group['rows']):0);$group['technical_rate']=$technical;$overallBudget+=$groupBudget;$overallExecuted+=$groupExecuted;$weightedTechnical+=$technical*$groupBudget;}unset($group);
        $overallTechnical=$overallBudget>0?$weightedTechnical/$overallBudget:(count($groups)?array_sum(array_column($groups,'technical_rate'))/count($groups):0);
        return ['groups'=>array_values($groups),'summary'=>['budget'=>$overallBudget,'executed'=>$overallExecuted,'technical_rate'=>$overallTechnical,'financial_rate'=>$overallBudget>0?min(100,$overallExecuted/$overallBudget*100):0]];
    }

    public function save(int $chantierId,int $preparationId,array $post,int $userId): void
    {
        $rows=is_array($post['tasks']??null)?$post['tasks']:[];$subtasks=is_array($post['subtasks']??null)?$post['subtasks']:[];$customRows=is_array($post['custom_tasks']??null)?$post['custom_tasks']:[];$customSubs=is_array($post['custom_subtasks']??null)?$post['custom_subtasks']:[];$groups=is_array($post['groups']??null)?$post['groups']:[];
        $allowed=$this->pdo->prepare("SELECT id,progress FROM planning_chantier_meeting_action_points WHERE id=:id AND chantier_id=:chantier AND preparation_id=:preparation AND archived_at IS NULL AND COALESCE(status,'open')<>'cancelled'");
        $upsert=$this->pdo->prepare("INSERT INTO planning_chantier_work_progress(action_point_id,unit_label,planned_quantity,executed_quantity,client_billed_amount,executed_billed_amount,observation,updated_by,updated_at) VALUES(:id,:unit,:planned,:executed,:billed,:executed_billed,:observation,:user,NOW()) ON DUPLICATE KEY UPDATE unit_label=VALUES(unit_label),planned_quantity=VALUES(planned_quantity),executed_quantity=VALUES(executed_quantity),client_billed_amount=VALUES(client_billed_amount),executed_billed_amount=VALUES(executed_billed_amount),observation=VALUES(observation),updated_by=VALUES(updated_by),updated_at=NOW()");
        $groupUpsert=$this->pdo->prepare("INSERT INTO planning_chantier_work_progress_groups(preparation_id,chantier_id,section_title,client_billed_amount,observation,updated_by,updated_at) VALUES(:preparation,:chantier,:title,:amount,:observation,:user,NOW()) ON DUPLICATE KEY UPDATE client_billed_amount=VALUES(client_billed_amount),observation=VALUES(observation),updated_by=VALUES(updated_by),updated_at=NOW()");
        $allowedSub=$this->pdo->prepare("SELECT cl.id FROM planning_chantier_meeting_action_point_checklist cl JOIN planning_chantier_meeting_action_points ap ON ap.id=cl.action_point_id WHERE cl.id=:id AND ap.chantier_id=:chantier AND ap.preparation_id=:preparation AND cl.archived_at IS NULL AND ap.archived_at IS NULL");$subUpsert=$this->pdo->prepare("INSERT INTO planning_chantier_work_progress_checklist(checklist_id,unit_label,planned_quantity,client_billed_amount,observation,updated_by,updated_at) VALUES(:id,:unit,:planned,:billed,:observation,:user,NOW()) ON DUPLICATE KEY UPDATE unit_label=VALUES(unit_label),planned_quantity=VALUES(planned_quantity),client_billed_amount=VALUES(client_billed_amount),observation=VALUES(observation),updated_by=VALUES(updated_by),updated_at=NOW()");
        $customUpsert=$this->pdo->prepare("INSERT INTO planning_chantier_work_progress_custom(preparation_id,chantier_id,item_key,unit_label,planned_quantity,client_billed_amount,observation,updated_by,updated_at) VALUES(:preparation,:chantier,:item_key,:unit,:planned,:billed,:observation,:user,NOW()) ON DUPLICATE KEY UPDATE unit_label=VALUES(unit_label),planned_quantity=VALUES(planned_quantity),client_billed_amount=VALUES(client_billed_amount),observation=VALUES(observation),updated_by=VALUES(updated_by),updated_at=NOW()");
        $customSections=$this->pdo->prepare('SELECT id,payload_json FROM planning_chantier_meeting_custom_sections WHERE preparation_id=:preparation AND chantier_id=:chantier AND archived_at IS NULL');$customSections->execute(['preparation'=>$preparationId,'chantier'=>$chantierId]);$allowedCustom=[];foreach($customSections->fetchAll(PDO::FETCH_ASSOC)?:[]as$section){$tasks=json_decode((string)$section['payload_json'],true);if(!is_array($tasks)||!$tasks)$tasks=[[]];foreach(array_values($tasks)as$taskIndex=>$task){$key=(int)$section['id'].':t:'.$taskIndex;$allowedCustom[$key]=true;foreach(array_values(is_array($task['checklist']??null)?$task['checklist']:[])as$subIndex=>$unused)$allowedCustom[$key.':s:'.$subIndex]=true;}}
        $customTaskIds=[];$customSubIds=[];foreach(array_keys($allowedCustom)as$key){if(preg_match('/^(\d+):t:(\d+)$/',$key,$match))$customTaskIds[-(((int)$match[1]*1000)+(int)$match[2]+1)]=$key;elseif(preg_match('/^(\d+):t:(\d+):s:(\d+)$/',$key,$match))$customSubIds[-(((int)$match[1]*10000)+((int)$match[2]*100)+(int)$match[3]+1)]=$key;}
        foreach($rows as$id=>$row)if((int)$id<0&&isset($customTaskIds[(int)$id])){$customRows[$customTaskIds[(int)$id]]=$row;unset($rows[$id]);}
        foreach($subtasks as$id=>$row)if((int)$id<0&&isset($customSubIds[(int)$id])){$customSubs[$customSubIds[(int)$id]]=$row;unset($subtasks[$id]);}
        $saveCustom=static function(array $items)use($customUpsert,$allowedCustom,$preparationId,$chantierId,$userId):void{foreach($items as$key=>$row){if(!isset($allowedCustom[$key])||!is_array($row))throw new DomainException('Une tâche libre ne fait pas partie de ce compte rendu.');$planned=max(0,(float)($row['planned_quantity']??0));if($planned<=0)throw new DomainException('La quantité prévue doit être supérieure à zéro.');$customUpsert->execute(['preparation'=>$preparationId,'chantier'=>$chantierId,'item_key'=>$key,'unit'=>mb_substr(trim((string)($row['unit_label']??'ens')),0,40),'planned'=>$planned,'billed'=>max(0,(float)($row['client_billed_amount']??0)),'observation'=>mb_substr(trim((string)($row['observation']??'')),0,500),'user'=>$userId]);}};
        $this->pdo->beginTransaction();try{foreach($rows as$id=>$row){$id=(int)$id;if($id<=0||!is_array($row))continue;$allowed->execute(['id'=>$id,'chantier'=>$chantierId,'preparation'=>$preparationId]);$point=$allowed->fetch(PDO::FETCH_ASSOC);if(!$point)throw new DomainException('Une tâche ne fait pas partie du chantier et de la réunion sélectionnés.');$planned=max(0,(float)($row['planned_quantity']??0));$billed=max(0,(float)($row['client_billed_amount']??0));if($planned<=0)throw new DomainException('La quantité prévue doit être supérieure à zéro.');$progress=min(100,max(0,(float)($point['progress']??0)));$upsert->execute(['id'=>$id,'unit'=>mb_substr(trim((string)($row['unit_label']??'ens')),0,40),'planned'=>$planned,'executed'=>$planned*$progress/100,'billed'=>$billed,'executed_billed'=>$billed*$progress/100,'observation'=>mb_substr(trim((string)($row['observation']??'')),0,500),'user'=>$userId]);}foreach($subtasks as$id=>$row){$id=(int)$id;if($id<=0||!is_array($row))continue;$allowedSub->execute(['id'=>$id,'chantier'=>$chantierId,'preparation'=>$preparationId]);if(!$allowedSub->fetchColumn())throw new DomainException('Une sous-tâche ne fait pas partie de cette réunion.');$planned=max(0,(float)($row['planned_quantity']??0));if($planned<=0)throw new DomainException('La quantité prévue d’une sous-tâche doit être supérieure à zéro.');$subUpsert->execute(['id'=>$id,'unit'=>mb_substr(trim((string)($row['unit_label']??'ens')),0,40),'planned'=>$planned,'billed'=>max(0,(float)($row['client_billed_amount']??0)),'observation'=>mb_substr(trim((string)($row['observation']??'')),0,500),'user'=>$userId]);}$saveCustom($customRows);$saveCustom($customSubs);foreach($groups as$row){if(!is_array($row))continue;$title=trim((string)($row['title']??''));if($title==='')continue;$groupUpsert->execute(['preparation'=>$preparationId,'chantier'=>$chantierId,'title'=>mb_substr($title,0,255),'amount'=>max(0,(float)($row['client_billed_amount']??0)),'observation'=>mb_substr(trim((string)($row['observation']??'')),0,500),'user'=>$userId]);}$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
    }
}
